63	    public function renkKaydet(Request $request)
64	    {
65	        $user = auth()->user();
66	        if (!$user) {
67	            return response()->json(['success' => false, 'message' => 'Oturum açmanız gerekli'], 401);
68	        }
69	
70	        $renkler = $request->input('renkler');
71	        $kalinliklar = $request->input('kalinliklar');
72	        if (!is_array($renkler)) {
73	            return response()->json(['success' => false, 'message' => 'Geçersiz veri'], 422);
74	        }
75	        if (!is_array($kalinliklar)) $kalinliklar = [];
76	
77	        $kaydedilen = 0;
78	
79	        foreach ($renkler as $layer => $hex) {
80	            if (!is_string($layer) || !is_string($hex)) continue;
81	            if (!preg_match('/^#[0-9A-Fa-f]{6}$/', $hex)) continue;
82	
83	            // Kalınlığı aynı satırda kaydet (kullanıcı width belirttiyse, yoksa 2)
84	            $width = isset($kalinliklar[$layer]) ? (int) $kalinliklar[$layer] : 2;
85	            if ($width < 1) $width = 1;
86	            if ($width > 10) $width = 10;
87	
88	            // Birincil depo: gis_katman_ayarlari.renk (Oracle dahil tüm ortamlarda var)
89	            try {
90	                \DB::table('gis_katman_ayarlari')->updateOrInsert(
91	                    ['user_id' => $user->id, 'katman_adi' => $layer],
92	                    [
93	                        'renk' => strtoupper($hex),
94	                        'stroke_width' => $width,
95	                        'gorunur' => true,
96	                        'opacity' => 0.70,
97	                        'created_at' => now(),
98	                        'updated_at' => now(),
99	                    ]
100	                );
101	                $kaydedilen++;
102	            } catch (\Exception $e) {
103	                Log::warning('[maps.renkKaydet] gis_katman_ayarlari kaydı başarısız: ' . $e->getMessage());
104	                continue;
105	            }
106	
107	            // İkincil yedek: users.map_preferences JSON — kolon yalnızca MySQL'de varsa yaz
108	            try {
109	                if (Schema::hasColumn('users', 'map_preferences')) {
110	                    $user->setMapColorSetting($layer, $hex);
111	                }
112	            } catch (\Exception $e) {
113	                // Oracle'da kolon yoksa sessiz geç
114	            }
115	        }
116	
117	        Log::info('[maps.renkKaydet] kullanıcı katman rengi + kalınlık kaydı (gis_katman_ayarlari)', [
118	            'user_id'     => $user->id,
119	            'toplam'      => $kaydedilen,
120	            'renkler'     => $renkler,
121	            'kalinliklar' => $kalinliklar,
122	            'kaydeden'    => $user->email ?? $user->name,
123	        ]);
124	
125	        return response()->json([
126	            'success' => true,
127	            'message' => $kaydedilen . ' katman rengi kaydedildi.',
128	            'kaydedilen' => $kaydedilen,
129	        ]);
130	    }
