170	    public function roadQuery(Request $request)
171	    {
172	        $hatKimligi = $request->input('hat_kimligi');
173	        $lat = $request->input('lat');
174	        $lng = $request->input('lng');
175	
176	        // Veri dosyalarını tara
177	        $files = [
178	            storage_path('shp/15_alti.js'),
179	            storage_path('shp/15_ustu.js'),
180	        ];
181	
182	        foreach ($files as $path) {
183	            if (!file_exists($path)) continue;
184	            $content = file_get_contents($path);
185	            $json = preg_replace('/^var\s+\w+\s*=\s*/', '', $content);
186	            $json = rtrim($json, ";\n\r ");
187	            $data = json_decode($json, true);
188	            if (!$data || !isset($data['features'])) continue;
189	
190	            foreach ($data['features'] as $feature) {
191	                $props = $feature['properties'] ?? [];
192	
193	                // Kimlik no ile ara
194	                if ($hatKimligi && ($props['CADDE_SOKA'] ?? null) == $hatKimligi) {
195	                    return response()->json([
196	                        'found' => true,
197	                        'source' => basename($path),
198	                        'properties' => $props,
199	                        'geometry' => $feature['geometry'],
200	                    ]);
201	                }
202	
203	                // Koordinat ile ara (noktanın 50m yakınındaki yol)
204	                if ($lat && $lng) {
205	                    $geomType = $feature['geometry']['type'] ?? '';
206	                    $coords = $feature['geometry']['coordinates'] ?? [];
207	                    // LineString → düz [lon,lat] listesi; MultiLineString → segment listesi
208	                    $segments = [];
209	                    if ($geomType === 'MultiLineString') {
210	                        $segments = $coords;
211	                    } elseif ($geomType === 'LineString') {
212	                        $segments = [$coords];
213	                    } elseif (is_array($coords) && isset($coords[0]) && is_array($coords[0]) && isset($coords[0][0]) && !is_array($coords[0][0])) {
214	                        $segments = [$coords];
215	                    } else {
216	                        $segments = $coords;
217	                    }
218	                    foreach ($segments as $segment) {
219	                        foreach ($segment as $coord) {
220	                            if (is_array($coord) && count($coord) >= 2) {
221	                                $d = $this->haversineDistance((float)$lat, (float)$lng, (float)$coord[1], (float)$coord[0]);
222	                                if ($d < 0.05) { // 50 metre
223	                                    return response()->json([
224	                                        'found' => true,
225	                                        'source' => basename($path),
226	                                        'properties' => $props,
227	                                        'distance_km' => round($d, 4),
228	                                    ]);
229	                                }
230	                            }
231	                        }
232	                    }
233	                }
234	            }
235	        }
236	
237	        return response()->json(['found' => false, 'error' => 'Yol bulunamadı']);
238	    }
239	
240	    private function haversineDistance($lat1, $lon1, $lat2, $lon2)
241	    {
242	        $R = 6371;
243	        $dLat = deg2rad($lat2 - $lat1);
244	        $dLon = deg2rad($lon2 - $lon1);
245	        $a = sin($dLat/2) * sin($dLat/2) + cos(deg2rad($lat1)) * cos(deg2rad($lat2)) * sin($dLon/2) * sin($dLon/2);
246	        $c = 2 * atan2(sqrt($a), sqrt(1-$a));
247	        return $R * $c;
248	    }
