434	    public function search(Request $request)
435	    {
436	        $q = $request->input('q');
437	        if (!$q || strlen(trim($q)) < 2) return response()->json([]);
438	        $q = trim($q);
439	
440	        $results = [];
441	        $cacheKey = 'maps_search_' . md5($q);
442	        $cached = \Illuminate\Support\Facades\Cache::get($cacheKey);
443	        if ($cached) return response()->json($cached);
444	
445	        // 0) LOCAL-FIRST — caddeler_ve_sokaklar.json + geometri (hız + %100 yerel veri).
446	        //    Mahalle + cadde/sokak eşleşmesi anında döner; WFS sadece parsel/ada yedeği.
447	        $results = array_merge($results, $this->searchLocal($q));
448	
449	        // Yerel cadde sonuçları yetersizse WFS cadde yedeği (geo3)
450	        $yerelCaddeSayisi = count(array_filter($results, fn ($r) => $r['type'] === 'cadde'));
451	        if ($yerelCaddeSayisi < 3) {
452	            try {
453	                $caddeUrl = 'https://geo3.sanliurfa.bel.tr:8091/geoserver/wfs'
454	                    . '?service=WFS&version=2.0.0&request=GetFeature'
455	                    . '&typeNames=cbs:MISMAP_CADDE_SOKAK'
456	                    . '&cql_filter=' . urlencode("CADDE_SO_1 ILIKE '%{$q}%' OR CADDE_SO_2 ILIKE '%{$q}%'")
457	                    . '&outputFormat=application/json&srsName=EPSG:4326&count=6';
458	                $resp = Http::withOptions(['verify' => false, 'timeout' => 5])->get($caddeUrl);
459	                if ($resp->successful()) {
460	                    $data = $resp->json();
461	                    if (!empty($data['features'])) {
462	                        foreach ($data['features'] as $f) {
463	                            $p = $f['properties'] ?? [];
464	                            $name = trim(($p['CADDE_SO_1'] ?? '') . ' ' . ($p['CADDE_SO_2'] ?? ''));
465	                            if (!$name) continue;
466	                            $center = $this->centroidFromGeoJson($f['geometry']);
467	                            if (!$center) continue;
468	                            $results[] = [
469	                                'type' => 'cadde',
470	                                'label' => $name,
471	                                'detail' => ($p['MAHALLE_AD'] ?? '') . ', ' . ($p['ILCE'] ?? ''),
472	                                'lat' => $center['lat'],
473	                                'lon' => $center['lng'],
474	                            ];
475	                        }
476	                    }
477	                }
478	            } catch (\Exception $e) {
479	                Log::warning('Cadde arama hatası: ' . $e->getMessage());
480	            }
481	        }
482	
483	        try {
484	            $parselUrl = 'https://geo3.sanliurfa.bel.tr:8091/geoserver/wfs'
485	                . '?service=WFS&version=2.0.0&request=GetFeature'
486	                . '&typeNames=smpns:MISMAP_NUM_KADASTRO_PARSEL'
487	                . '&cql_filter=' . urlencode("ADA ILIKE '%{$q}%' OR PARSEL ILIKE '%{$q}%'")
488	                . '&outputFormat=application/json&srsName=EPSG:4326&count=5';
489	            $resp = Http::withOptions(['verify' => false, 'timeout' => 5])->get($parselUrl);
490	            if ($resp->successful()) {
491	                $data = $resp->json();
492	                if (!empty($data['features'])) {
493	                    foreach ($data['features'] as $f) {
494	                        $p = $f['properties'] ?? [];
495	                        $label = 'Ada ' . ($p['ADA'] ?? '') . ' / Parsel ' . ($p['PARSEL'] ?? '');
496	                        $center = $this->centroidFromGeoJson($f['geometry']);
497	                        if (!$center) continue;
498	                        $results[] = [
499	                            'type' => 'parsel',
500	                            'label' => $label,
501	                            'detail' => ($p['MAHALLE_AD'] ?? '') . ', ' . ($p['ILCE'] ?? ''),
502	                            'lat' => $center['lat'],
503	                            'lon' => $center['lng'],
504	                        ];
505	                    }
506	                }
507	            }
508	        } catch (\Exception $e) {
509	            Log::warning('Parsel arama hatası: ' . $e->getMessage());
510	        }
511	
512	        $seen = [];
513	        $filtered = [];
514	        foreach ($results as $r) {
515	            $key = round($r['lat'], 5) . '|' . round($r['lon'], 5);
516	            if (isset($seen[$key])) continue;
517	            $seen[$key] = true;
518	            $filtered[] = $r;
519	            if (count($filtered) >= 15) break;
520	        }
521	
522	        \Illuminate\Support\Facades\Cache::put($cacheKey, $filtered, now()->addMinutes(10));
523	
524	        return response()->json($filtered);
525	    }
