527	    /**
528	     * LOCAL-FIRST arama — caddeler_ve_sokaklar.json (mahalle + cadde/sokak) +
529	     * geometri centroid'i. WFS'e gerek kalmadan anında sonuç üretir.
530	     * @return array<int, array{type:string,label:string,detail:string,lat:float,lon:float}>
531	     */
532	    private function searchLocal(string $q): array
533	    {
534	        $path = storage_path('shp/caddeler_ve_sokaklar.json');
535	        if (!file_exists($path)) return [];
536	        $content = file_get_contents($path);
537	        if (!$content) return [];
538	
539	        $fixed = preg_replace('/\}\s*\n\s*\{/', '},' . "\n" . '{', $content);
540	        $data = json_decode('[' . $fixed . ']', true);
541	        if (!is_array($data)) return [];
542	
543	        $qU = $this->trUppercase(trim($q));
544	        if ($qU === '') return [];
545	
546	        // Hızlı geometri centroid index (bir kez oku, tekrar tekrar centroid)
547	        $geomIndex = $this->geomCentroidIndex();
548	
549	        $results = [];
550	        $mahalleSet = [];      // mahalle → koordinat toplamı (centroid ortalaması için)
551	        $mahalleCount = [];
552	
553	        foreach ($data as $r) {
554	            $mahalle = trim((string) ($r['MAHALLE_AD'] ?? ''));
555	            $caddeAdi = trim((string) ($r['CADDE SOKAK ADI'] ?? ''));
556	            if ($mahalle === '') continue;
557	
558	            $mahU = $this->trUppercase($mahalle);
559	
560	            // 1) MAHALLE EŞLEŞMESİ
561	            if (str_contains($mahU, $qU)) {
562	                $csa = (int) ($r['CADDE_SOKA'] ?? 0);
563	                $coord = $csa > 0 ? ($geomIndex[$csa] ?? null) : null;
564	                if ($coord) {
565	                    if (!isset($mahalleSet[$mahU])) {
566	                        $mahalleSet[$mahU] = ['ad' => $mahalle, 'lat' => 0, 'lon' => 0];
567	                        $mahalleCount[$mahU] = 0;
568	                    }
569	                    $mahalleSet[$mahU]['lat'] += $coord['lat'];
570	                    $mahalleSet[$mahU]['lon'] += $coord['lng'];
571	                    $mahalleCount[$mahU]++;
572	                }
573	            }
574	
575	            // 2) CADDE/SOKAK EŞLEŞMESİ
576	            // 2) CADDE/SOKAK EŞLEŞMESİ — sayısal sorguda ters-substring istemeyiz (8013→"1" gürültü)
577	            $caddeU = $this->trUppercase($caddeAdi);
578	            $qIsNumeric = preg_match('/^\d+$/', $qU);
579	            $caddeDirTan = $this->containsU($caddeU, $qU);
580	            $caddeTers = !$qIsNumeric && mb_strlen($caddeU) >= 3 && $this->containsU($qU, $caddeU);
581	            if ($caddeAdi !== '' && ($caddeDirTan || $caddeTers)) {
582	                $csa = (int) ($r['CADDE_SOKA'] ?? 0);
583	                $coord = $csa > 0 ? ($geomIndex[$csa] ?? null) : null;
584	                $sorumluluk = trim((string) ($r['SORUMLULUK'] ?? ''));
585	                $genislik = (float) ($r['GENISLIGI'] ?? 0);
586	                $results[] = [
587	                    'type' => 'cadde',
588	                    'label' => $caddeAdi,
589	                    'detail' => $mahalle . ($sorumluluk !== '' ? ' · ' . $sorumluluk : '') . ($genislik > 0 ? ' · ' . $genislik . ' m' : ''),
590	                    'lat' => $coord ? $coord['lat'] : 0,
591	                    'lon' => $coord ? $coord['lng'] : 0,
592	                ];
593	            }
594	        }
595	
596	        // Mahalle sonuçları (cadde centroid ortalaması)
597	        foreach ($mahalleSet as $mahU => $m) {
598	            if (($mahalleCount[$mahU] ?? 0) <= 0) continue;
599	            $results[] = [
600	                'type' => 'mahalle',
601	                'label' => $m['ad'],
602	                'detail' => 'Eyyübiye',
603	                'lat' => round($m['lat'] / $mahalleCount[$mahU], 7),
604	                'lon' => round($m['lon'] / $mahalleCount[$mahU], 7),
605	            ];
606	        }
607	
608	        // En fazla 12 sonuç (cadde öncelik, mahalle sonra)
609	        usort($results, function ($a, $b) {
610	            if ($a['type'] === $b['type']) return 0;
611	            return $a['type'] === 'cadde' ? -1 : 1;
612	        });
613	        $results = array_slice($results, 0, 12);
614	
615	        return $results;
616	    }
