655	    /**
656	     * WMS NOKTA ATIŞI ADRES BULMA — tam adres metnini çöz, WFS'ten doğrula.
657	     * "15 TEMMUZ MAHALLESİ, 123. SOKAK, 5" → mahalle + cadde/sokak + kapı no.
658	     * S2S: GeoServer (geo3) WFS 2.0.0 sorguları doğrudan Http ile (proxy'siz).
659	     */
660	    public function adresAra(Request $request)
661	    {
662	        $q = trim((string) ($request->input('q') ?? $request->input('adres') ?? ''));
663	        if ($q === '' || mb_strlen($q) < 3) {
664	            return response()->json(['success' => false, 'message' => 'Adres çok kısa.']);
665	        }
666	
667	        $cacheKey = 'maps_adres_ara_' . md5(mb_strtolower($q, 'UTF-8'));
668	        $cached = \Illuminate\Support\Facades\Cache::get($cacheKey);
669	        if ($cached) return response()->json($cached);
670	
671	        $parsed = $this->parseAddress($q);
672	
673	        $sonuc = ['success' => false, 'message' => 'Adres isabetli bulunamadı.'];
674	
675	        if ($parsed['cadde'] !== '') {
676	            // LOCAL-FIRST — caddeler_ve_sokaklar.json + 15_alti/15_ustu geometrisi.
677	            // Doğru adres, WFS'e gerek kalmadan yerel veriden bulunur (hız + isabet).
678	            $yerel = $this->localCaddeBul($parsed['cadde'], $parsed['mahalle']);
679	            if ($yerel && isset($yerel['lat'], $yerel['lon']) && $yerel['lat'] !== null && $yerel['lon'] !== null) {
680	                $sonuc = array_merge($sonuc, [
681	                    'success' => true,
682	                    'lat' => round((float) $yerel['lat'], 7),
683	                    'lon' => round((float) $yerel['lon'], 7),
684	                    'mahalle' => $yerel['mahalle'],
685	                    'cadde' => $yerel['name'],
686	                    'kapi' => $parsed['kapi'],
687	                    'detail' => trim(implode(', ', array_filter([
688	                        $yerel['mahalle'],
689	                        $yerel['name'],
690	                        $parsed['kapi'],
691	                    ]))),
692	                    'sorumluluk' => $yerel['sorumluluk'],
693	                    'genislik' => $yerel['genislik'],
694	                    'source' => 'local',
695	                    'confidence' => 'yuksek',
696	                ]);
697	                \Illuminate\Support\Facades\Cache::put($cacheKey, $sonuc, now()->addMinutes(10));
698	                return response()->json($sonuc);
699	            }
700	        }
701	
702	        // WFS YEDEĞİ — yerel veride bulunamazsa geoserver (geo3) doğrulaması.
703	        try {
704	            // 1) MAHALLE — cbs:MISMAP_MAHALLE_KOYLER (geo3), MAHALLE_ADI
705	            $mahalle = null;
706	            if ($parsed['mahalle'] !== '') {
707	                $mahalle = $this->wfsMahalleBul($parsed['mahalle']);
708	                if ($mahalle) $sonuc['mahalle'] = $mahalle['name'];
709	            }
710	
711	            // 2) CADDE/SOKAK — mahalle poligonunun bboxı içinde ara (isabetli)
712	            $cadde = null;
713	            if ($parsed['cadde'] !== '') {
714	                $cadde = $this->wfsCaddeBul($parsed['cadde'], $mahalle);
715	                if ($cadde) $sonuc['cadde'] = $cadde['name'];
716	            }
717	
718	            // 3) KAPI NO
719	            $kapi = $parsed['kapi'];
720	            $sonuc['kapi'] = $kapi;
721	
722	            // Koordinat önceliği: cadde > mahalle merkezi
723	            $lat = $cadde['lat'] ?? $mahalle['lat'] ?? null;
724	            $lon = $cadde['lon'] ?? $mahalle['lon'] ?? null;
725	
726	            if ($lat !== null && $lon !== null) {
727	                $sonuc = array_merge($sonuc, [
728	                    'success' => true,
729	                    'lat' => round((float) $lat, 7),
730	                    'lon' => round((float) $lon, 7),
731	                    'detail' => trim(implode(', ', array_filter([
732	                        $sonuc['mahalle'] ?? null,
733	                        $sonuc['cadde'] ?? null,
734	                        $kapi,
735	                    ]))),
736	                    'confidence' => $cadde ? 'yuksek' : ($mahalle ? 'orta' : 'dusuk'),
737	                ]);
738	            }
739	        } catch (\Exception $e) {
740	            Log::warning('Adres ara hatası: ' . $e->getMessage());
741	        }
742	
743	        \Illuminate\Support\Facades\Cache::put($cacheKey, $sonuc, now()->addMinutes(10));
744	        return response()->json($sonuc);
745	    }
