747	    /**
748	     * LOCAL-FIRST cadde çözümü — caddeler_ve_sokaklar.json + geometri (CADDE_SOKA köprüsü).
749	     * Mahalle + cadde no verilir; yerel veride CADDE_SOKA ile eşleşen kaydın
750	     * 15_alti.js/15_ustu.js geometrisinden centroid koordinatı döner.
751	     * @return array|null ['name','mahalle','lat','lon','sorumluluk','genislik','source']
752	     */
753	    private function localCaddeBul(string $cadde, string $mahalle = ''): ?array
754	    {
755	        $path = storage_path('shp/caddeler_ve_sokaklar.json');
756	        if (!file_exists($path)) return null;
757	        $json = file_get_contents($path);
758	        if (!$json) return null;
759	
760	        // NDJSON normalize (JSON array'e çevir)
761	        $fixed = preg_replace('/\}\s*\n\s*\{/', '},' . "\n" . '{', $json);
762	        $data  = json_decode('[' . $fixed . ']', true);
763	        if (!is_array($data)) return null;
764	
765	        $caddeNo = trim((string) $cadde);
766	        if ($caddeNo === '') return null;
767	
768	        // CADDE_SOKA ADI alanı sayısal olabilir ("8013") — string karşılaştır
769	        $adaylar = [];
770	        $mahU = $this->trUppercase(trim($mahalle));
771	        foreach ($data as $r) {
772	            $ad = trim((string) ($r['CADDE SOKAK ADI'] ?? ''));
773	            if ($ad === '' || ltrim($ad, '0') !== ltrim($caddeNo, '0')) continue;
774	            $adaylar[] = $r;
775	        }
776	        if (empty($adaylar)) return null;
777	
778	        // Mahalle varsa onunla eşleştir
779	        $secim = null;
780	        $secimMahalle = null;
781	        foreach ($adaylar as $a) {
782	            $m = trim((string) ($a['MAHALLE_AD'] ?? ''));
783	            if ($mahU !== '' && $this->trUppercase($m) === $mahU) {
784	                $secim = $a;
785	                $secimMahalle = $m;
786	                break;
787	            }
788	        }
789	        if (!$secim) {
790	            $secim = $adaylar[0];
791	            $secimMahalle = trim((string) ($secim['MAHALLE_AD'] ?? ''));
792	        }
793	
794	        $csa = (int) ($secim['CADDE_SOKA'] ?? 0);
795	
796	        // Geometri centroid — 15_alti.js + 15_ustu.js
797	        $coord = $this->shpCaddeSokaCentroid($csa);
798	
799	        return [
800	            'name' => trim((string) ($secim['CADDE SOKAK ADI'] ?? $caddeNo)),
801	            'mahalle' => $secimMahalle,
802	            'lat' => $coord ? $coord['lat'] : null,
803	            'lon' => $coord ? $coord['lng'] : null,
804	            'sorumluluk' => trim((string) ($secim['SORUMLULUK'] ?? '')),
805	            'genislik' => (float) ($secim['GENISLIGI'] ?? 0),
806	            'source' => 'local',
807	        ];
808	    }
