827	            $fdc = json_decode($json, true);
828	            if (!is_array($fdc) || !isset($fdc['features'])) continue;
829	
830	            foreach ($fdc['features'] as $f) {
831	                $cid = (int) ($f['properties']['CADDE_SOKA'] ?? 0);
832	                if ($cid !== $caddeSoka) continue;
833	                $centroid = $this->centroid($f['geometry'] ?? []);
834	                if ($centroid) return $centroid;
