873	    /**
874	     * Türkçe adres çözücü — "8125. Sk. 122 Kadıkendi, 63000 Eyyübiye/Şanlıurfa"
875	     * → {mahalle:'Kadıkendi', cadde:'8125', kapi:'122'}
876	     * Formatlar: "MAHALLE + CADDE + KAPI", "Kadıkendi 8125. Sokak", "15 TEMMUZ MAHALLESİ, 123. Sokak, 5"
877	     */
878	    private function parseAddress(string $q): array
879	    {
880	        $mahalle = '';
881	        $cadde = '';
882	        $kapi = '';
883	
884	        // 1) Şehir/ilçe/posta kodu temizle (sadece mahalle+cadde+kapi kalır)
885	        $temiz = preg_replace('/\b\d{5}\b\s*/', ' ', $q);
886	        $temiz = str_replace(['/', ';'], ',', $temiz);
887	        $parcalar = array_values(array_filter(array_map('trim', explode(',', $temiz)), fn ($p) => $p !== ''));
888	        $parcalar = array_values(array_filter($parcalar, function ($p) {
889	            return ! preg_match('/(eyyübiye|şanlıurfa|sanliurfa|yyübiye)/iu', $p);
890	        }));
891	        $asil = implode(' ', $parcalar);
892	
893	        // 2) Sokak no: sayı + SK/SOK/CADDE etiketi ("8125. Sk.", "123. Sokak", "3097 SOKAK")
894	        if (preg_match('/(?:^|[\s,])?(\d{1,5})[\s\.]*\.?\s*(?:SK\.?|SOK\.?|SOKAK|SOKAĞI|SK|Cad\.?|CADDE|CD\.?|Cd\.?)/iu', $asil, $m)) {
895	            $cadde = $m[1];
896	        } elseif (preg_match('/(\d{1,5})\s+(?:SOKAK|SOKAĞI|SK|SOK|CADDE|CAD)/iu', $asil, $m2)) {
897	            $cadde = $m2[1];
898	        } elseif (preg_match('/^(\d{1,5})/u', $asil, $m3)) {
899	            $cadde = $m3[1];
900	        }
901	
902	        // 3) Kapı no: cadde numarasından SONRAKİ sayı (122) — sokak no karşıolmaz
903	        if ($cadde !== '') {
904	            $pos = strpos($asil, $cadde);
905	            $sonrasi = substr($asil, $pos + strlen($cadde));
906	            if (preg_match('/(\d{1,4}[A-Za-z]?)/u', $sonrasi, $mk)) {
907	                // "122" gibi — etiketsiz ilk sayı kapı no
908	                $kapi = $mk[1];
909	            }
910	        }
911	
912	        // 4) Mahalle: "MAHALLESİ" ekiyle biten grup VEYA sayı/etiket içermeyen son kelime
913	        if (preg_match('/([A-Za-zÇĞİÖŞÜçğıöşü0-9\s\.\-]*?(?:MAHALLESİ|MAHALESİ|MAHALLE|MAH\.|MAH|MH))/iu', $asil, $mm)) {
914	            $mahalle = trim($mm[1]);
915	        } elseif (preg_match_all('/\b([A-Za-zÇĞİÖŞÜçğıöşü]{3,})\b/iu', $asil, $kelt)) {
916	            $etiketler = ['SK', 'SOK', 'SOKAK', 'SOKAĞI', 'CAD', 'CADDE', 'CD', 'MAH', 'MAHALLE', 'MAHALLESİ', 'MH'];
917	            $adaylar = array_values(array_filter($kelt[1], function ($w) use ($etiketler) {
918	                $u = mb_strtoupper($w, 'UTF-8');
919	                $etiks = array_map(fn ($e) => mb_strtoupper($e, 'UTF-8'), $etiketler);
920	                return ! in_array($u, $etiks, true) && mb_strlen($w, 'UTF-8') >= 4;
921	            }));
922	            if (! empty($adaylar)) {
923	                $mahalle = mb_convert_case(end($adaylar), MB_CASE_TITLE, 'UTF-8');
924	            }
925	        }
926	
927	        // 5) Mahalle eklerini temizle: "BATIKENT MAHALLESİ"/"BATIKENT MAH." → "BATIKENT"
928	        // (local JSON MAHALLE_AD ve WFS MAHALLE_ADI ek'sizdir — ILIKE/local eşleşme için şart)
929	        if ($mahalle !== '') {
930	            $mahalle = trim((string) preg_replace(
931	                '/\s*(?:MAHALLESİ|MAHALESİ|MAHALLE|MAH\.|MAH|MH)\s*$/iu',
932	                '',
933	                $mahalle
934	            ));
935	        }
936	
937	        return ['mahalle' => $mahalle, 'cadde' => $cadde, 'kapi' => $kapi];
938	    }
