953	    /**
954	     * Ortak WFS HTTP client — WFS 1.1.0 (Opus'tan doğrulanmış, 2.0.0'dan stabil).
955	     * BBOX query parametresi: "minLng,minLat,maxLng,maxLat,EPSG:4326"
956	     */
957	    private function wfsGet(array $params): array
958	    {
959	        $defaults = [
960	            'service'      => 'WFS',
961	            'version'      => '1.1.0',
962	            'request'      => 'GetFeature',
963	            'outputFormat' => 'application/json',
964	            'srsName'      => 'EPSG:4326',
965	        ];
966	
967	        $query = array_merge($defaults, $params);
968	
969	        $resp = Http::withOptions(['verify' => false, 'timeout' => 15])->get(self::WFS_URL, $query);
970	
971	        if (!$resp->successful()) {
972	            Log::warning('[maps.wfsGet] Hata', ['status' => $resp->status(), 'params' => $query]);
973	            throw new \Exception("WFS HTTP {$resp->status()}");
974	        }
975	
976	        return $resp->json();
977	    }
