979	    /**
980	     * GET /maps/mahalleler — tüm Eyyübiye mahalleleri (cache'li, client-side arama).
981	     * Her mahalle: {ad, center:{lat,lng}, bbox:{minLng,minLat,maxLng,maxLat}}
982	     */
983	    public function mahalleler(Request $request)
984	    {
985	        $cacheKey = 'wfs_mahalleler_' . self::EYYUBIYE_ILCE_NO;
986	
987	        $result = \Illuminate\Support\Facades\Cache::remember($cacheKey, self::CACHE_TTL, function () {
