1145	    /** GeoJSON geometrisinden centroid (tüm tipler: Point/Polygon/LineString/Multi*). */
1146	    private function centroid(array $geometry): ?array
1147	    {
1148	        $coords = [];
1149	        $this->flattenCoords($geometry['coordinates'] ?? [], $coords);
1150	        if (empty($coords)) return null;
1151	
1152	        return [
1153	            'lat' => round(array_sum(array_column($coords, 1)) / count($coords), 7),
1154	            'lng' => round(array_sum(array_column($coords, 0)) / count($coords), 7),
1155	        ];
1156	    }
1157	
1158	    /** Koordinat dizisini düzleştirir. */
1159	    private function flattenCoords(array $arr, array &$out): void
1160	    {
1161	        if (isset($arr[0]) && is_numeric($arr[0])) {
1162	            $out[] = $arr;
1163	            return;
1164	        }
1165	        foreach ($arr as $item) {
1166	            if (is_array($item)) {
1167	                $this->flattenCoords($item, $out);
1168	            }
1169	        }
1170	    }
