1172	    /** GeoJSON geometrisinden bbox. */
1173	    private function getBbox(array $geometry): ?array
1174	    {
1175	        $coords = [];
1176	        $this->flattenCoords($geometry['coordinates'] ?? [], $coords);
1177	        if (empty($coords)) return null;
1178	
1179	        $lngs = array_column($coords, 0);
1180	        $lats = array_column($coords, 1);
1181	
1182	        return [
1183	            'minLng' => min($lngs),
1184	            'minLat' => min($lats),
1185	            'maxLng' => max($lngs),
1186	            'maxLat' => max($lats),
1187	            'bbox' => implode(',', [min($lngs), min($lats), max($lngs), max($lats)]),
1188	        ];
1189	    }
