1210	            // EYYÜBİYE İLÇE FİLTRESİ: aynı isimli mahalle başka ilçede olmasın
1211	            $u = $url . '&cql_filter=' . urlencode("MAHALLE_ADI ILIKE '%{$q}%' AND ILCE_NO=" . self::EYYUBIYE_ILCE_NO) . '&outputFormat=application/json&srsName=EPSG:4326&count=1';
