1387	    /**
1388	     * Türkçe/ASCII karakter varyantları — GeoServer ILIKE 'İ' vs 'I' ayrımı yapmaz.
1389	     * Girdi 'Kadıkendi' ise Türkçe doğru büyütme 'KADIKENDİ' (noktalı İ) üretir;
1390	     * 'md_strtoupper' ASCII 'I' üretir. İkisi de GeoServer sorgularında denenir.
1391	     * @return list<string>
1392	     */
1393	    private function turkeVariants(string $ad): array
1394	    {
1395	        $ad = trim($ad);
1396	        if ($ad === '') return [];
1397	
1398	        $tr = $this->trUppercase($ad);            // Kadıkendi → KADIKENDİ
1399	        $ascii = strtr($tr, ['İ' => 'I', 'Ş' => 'S', 'Ğ' => 'G', 'Ü' => 'U', 'Ö' => 'O', 'Ç' => 'C']);
1400	
1401	        $list = array_values(array_unique(array_filter([$ad, $tr, $ascii], fn ($v) => $v !== '')));
1402	
1403	        return $list;
1404	    }
