1406	    /**
1407	     * Türkçe kurallı büyük harfe çevirir: küçük i → büyük İ (noktalı),
1408	     * küçük ı → büyük I (noktasız) — mb_strtoupper'ın İ→I hatasını düzeltir.
1409	     */
1410	    private function trUppercase(string $s): string
1411	    {
1412	        $out = '';
1413	        $len = mb_strlen($s, 'UTF-8');
1414	        for ($i = 0; $i < $len; $i++) {
1415	            $ch = mb_substr($s, $i, 1, 'UTF-8');
1416	            $out .= match ($ch) {
1417	                'i' => 'İ',
1418	                'ı' => 'I',
1419	                'ş' => 'Ş', 'ğ' => 'Ğ', 'ü' => 'Ü', 'ö' => 'Ö', 'ç' => 'Ç',
1420	                default => mb_strtoupper($ch, 'UTF-8'),
1421	            };
1422	        }
1423	
1424	        return $out;
1425	    }
