1427	    private function centroidFromGeoJson($geom)
1428	    {
1429	        if (!$geom) return null;
1430	        $type = $geom['type'] ?? '';
1431	        $coords = $geom['coordinates'] ?? [];
1432	
1433	        if ($type === 'Point') {
1434	            return ['lng' => $coords[0], 'lat' => $coords[1]];
1435	        }
1436	
1437	        $points = [];
1438	        if ($type === 'Polygon') {
1439	            $points = $coords[0] ?? [];
1440	        } elseif ($type === 'MultiLineString' || $type === 'MultiPolygon') {
1441	            $ring = $coords[0][0] ?? $coords[0] ?? [];
1442	            $points = $ring;
1443	        } elseif ($type === 'LineString') {
1444	            $points = $coords;
1445	        }
1446	
1447	        if (empty($points)) return null;
1448	
1449	        $sumLat = 0; $sumLng = 0; $count = 0;
1450	        foreach ($points as $p) {
1451	            if (is_array($p) && count($p) >= 2) {
1452	                $sumLng += $p[0];
1453	                $sumLat += $p[1];
1454	                $count++;
1455	            }
1456	        }
1457	        if ($count === 0) return null;
1458	
1459	        return ['lng' => $sumLng / $count, 'lat' => $sumLat / $count];
1460	    }
